#!/usr/bin/env python3
"""
make_smartcard_iso7816_library.py

One-file generator for the final ISO7816 SmartCard KiCad library.

It creates:
  SmartCard_ISO7816.kicad_sym
  SmartCard_ISO7816.pretty/ISO7816_CardPads_Clean_Functional.kicad_mod

Pin/pad map:
  1 = VCC
  2 = RST
  3 = CLK
  4 = AUX1
  5 = GND
  6 = VPP/NC
  7 = I/O
  8 = AUX2

Notes:
  - Footprint uses real numbered custom SMD pads.
  - Visible pad number text is removed.
  - Symbol pins 1..8 match footprint pads 1..8.
"""

