PIN_MAP = {
    "1": "VCC",
    "2": "RST",
    "3": "CLK",
    "4": "AUX1",
    "5": "GND",
    "6": "VPP/NC",
    "7": "I/O",
    "8": "AUX2",
}

def write_library(out_dir: Path) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    pretty_dir = out_dir / "SmartCard_ISO7816.pretty"
    pretty_dir.mkdir(parents=True, exist_ok=True)

    symbol_path = out_dir / "SmartCard_ISO7816.kicad_sym"
    footprint_path = pretty_dir / "ISO7816_CardPads_Clean_Functional.kicad_mod"
    readme_path = out_dir / "README_ISO7816.txt"
    layout_path = out_dir / "smartcard_iso7816_layout.json"

    symbol_path.write_text(SYMBOL_TEXT)
    footprint_path.write_text(FOOTPRINT_TEXT)
    layout_path.write_text(json.dumps({"pin_map": PIN_MAP}, indent=2))

    readme_path.write_text(
        "SmartCard ISO7816 KiCad Library\n"
        "================================\n\n"
        "Symbol library:\n"
        "  SmartCard_ISO7816.kicad_sym\n\n"
        "Footprint library:\n"
        "  SmartCard_ISO7816.pretty/ISO7816_CardPads_Clean_Functional.kicad_mod\n\n"
        "Pin/pad map:\n"
        "  1 = VCC\n"
        "  2 = RST\n"
        "  3 = CLK\n"
        "  4 = AUX1\n"
        "  5 = GND\n"
        "  6 = VPP/NC\n"
        "  7 = I/O\n"
        "  8 = AUX2\n\n"
        "KiCad import:\n"
        "  Add SmartCard_ISO7816.kicad_sym as a symbol library.\n"
        "  Add SmartCard_ISO7816.pretty as a footprint library.\n"
    )

    print(f"Wrote {symbol_path}")
    print(f"Wrote {footprint_path}")
    print(f"Wrote {readme_path}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--out-dir", type=Path, default=Path("SmartCard_ISO7816_Library"))
    args = parser.parse_args()
    write_library(args.out_dir)

if __name__ == "__main__":
    main()
